import Foundation

// Generated from the user-provided USAF scoring charts effective 1 Mar 2026
// and Navy Guide-5A dated Dec 2025. Values are exact discrete table thresholds.

public enum ServiceSex: String, Codable, CaseIterable { case male, female }

public struct ScoreThreshold: Codable, Hashable {
    public let threshold: Double
    public let points: Double
    public init(threshold: Double, points: Double) { self.threshold = threshold; self.points = points }
}

public enum ThresholdDirection: String, Codable { case higherIsBetter, lowerIsBetter }

public enum TableScorer {
    public static func score(value: Double, thresholds: [ScoreThreshold], direction: ThresholdDirection) -> Double? {
        switch direction {
        case .higherIsBetter:
            return thresholds.sorted { $0.threshold > $1.threshold }.first(where: { value >= $0.threshold })?.points
        case .lowerIsBetter:
            return thresholds.sorted { $0.threshold < $1.threshold }.first(where: { value <= $0.threshold })?.points
        }
    }
}

// MARK: - Air Force
public enum AirForceAgeBand: String, Codable, CaseIterable {
    case under25
    case age25to29
    case age30to34
    case age35to39
    case age40to44
    case age45to49
    case age50to54
    case age55to59
    case age60Plus
    public init(age: Int) {
        switch age { case ..<25: self = .under25; case 25...29: self = .age25to29; case 30...34: self = .age30to34; case 35...39: self = .age35to39; case 40...44: self = .age40to44; case 45...49: self = .age45to49; case 50...54: self = .age50to54; case 55...59: self = .age55to59; default: self = .age60Plus }
    }
}
public enum AirForceWalkAgeBand: String, Codable { case under30, age30to39, age40to49, age50to59, age60Plus; public init(age: Int) { switch age { case ..<30:self = .under30; case 30...39:self = .age30to39; case 40...49:self = .age40to49; case 50...59:self = .age50to59; default:self = .age60Plus } } }
public enum AirForceEvent: String, Codable, CaseIterable { case waistToHeightRatio, pushUps, handReleasePushUps, sitUps, crossLegReverseCrunch, forearmPlank, twoMileRun, hamr20m }
public struct AirForceProfile: Hashable, Codable { public let ageBand: AirForceAgeBand; public let sex: ServiceSex; public init(age: Int, sex: ServiceSex) { self.ageBand = .init(age: age); self.sex = sex }; public init(ageBand: AirForceAgeBand, sex: ServiceSex) { self.ageBand = ageBand; self.sex = sex } }
public enum AirForceScoring {
    public static func score(event: AirForceEvent, rawValue: Double, age: Int, sex: ServiceSex) -> Double? {
        let profile = AirForceProfile(age: age, sex: sex)
        guard let table = tables[event]?[profile] else { return nil }
        return TableScorer.score(value: rawValue, thresholds: table.thresholds, direction: table.direction)
    }
    public static func waistToHeightRatio(waist: Double, height: Double) -> Double? { guard waist > 0, height > 0 else { return nil }; return waist / height }
