// MARK: - Navy
public enum NavyAgeBand: String, Codable, CaseIterable {
    case age17to19
    case age20to24
    case age25to29
    case age30to34
    case age35to39
    case age40to44
    case age45to49
    case age50to54
    case age55to59
    case age60to64
    case age65Plus
    public init(age: Int) { switch age { case ...19:self = .age17to19; case 20...24:self = .age20to24; case 25...29:self = .age25to29; case 30...34:self = .age30to34; case 35...39:self = .age35to39; case 40...44:self = .age40to44; case 45...49:self = .age45to49; case 50...54:self = .age50to54; case 55...59:self = .age55to59; case 60...64:self = .age60to64; default:self = .age65Plus } }
}
public enum NavyAltitude: String, Codable { case below5000, above5000 }
public enum NavyEvent: String, Codable, CaseIterable { case pushUps, forearmPlank, run1_5Mile, row2Kilometer, swim500Yard, swim450Meter }
public enum NavyPerformanceCategory: String, Codable { case outstanding, excellent, good, satisfactory, probationary, failure }
public enum NavyPerformanceLevel: String, Codable { case high, medium, low, none }
public struct NavyProfile: Hashable, Codable { public let ageBand: NavyAgeBand; public let sex: ServiceSex; public let altitude: NavyAltitude; public init(age: Int, sex: ServiceSex, altitude: NavyAltitude) { self.ageBand = .init(age: age); self.sex = sex; self.altitude = altitude }; public init(ageBand: NavyAgeBand, sex: ServiceSex, altitude: NavyAltitude) { self.ageBand = ageBand; self.sex = sex; self.altitude = altitude } }
public struct NavyStandardRow: Codable, Hashable {
    public let points: Int; public let category: NavyPerformanceCategory; public let level: NavyPerformanceLevel; public let pushUps: Int; public let forearmPlankSeconds: Int; public let runSeconds: Int; public let rowSeconds: Int; public let swim500YardSeconds: Int; public let swim450MeterSeconds: Int
}
public struct NavyEventResult: Codable { public let points: Int; public let category: NavyPerformanceCategory; public let level: NavyPerformanceLevel }
public enum NavyScoring {
    public static func score(event: NavyEvent, rawValue: Int, age: Int, sex: ServiceSex, altitude: NavyAltitude) -> NavyEventResult {
        let profile = NavyProfile(age: age, sex: sex, altitude: altitude); guard let rows = tables[profile] else { return .init(points: 0, category: .failure, level: .none) }
        let matched: NavyStandardRow?
        switch event {
        case .pushUps: matched = rows.first(where: { rawValue >= $0.pushUps })
        case .forearmPlank: matched = rows.first(where: { rawValue >= $0.forearmPlankSeconds })
        case .run1_5Mile: matched = rows.first(where: { rawValue <= $0.runSeconds })
        case .row2Kilometer: matched = rows.first(where: { rawValue <= $0.rowSeconds })
        case .swim500Yard: matched = rows.first(where: { rawValue <= $0.swim500YardSeconds })
        case .swim450Meter: matched = rows.first(where: { rawValue <= $0.swim450MeterSeconds })
        }
        guard let row = matched else { return .init(points: 0, category: .failure, level: .none) }
        return .init(points: row.points, category: row.category, level: row.level)
    }
    public static func overall(events: [NavyEventResult]) -> NavyEventResult? { guard !events.isEmpty else { return nil }; let average = Double(events.reduce(0) { $0 + $1.points }) / Double(events.count); let rounded = Int(average.rounded(.down)); return category(forAveragePoints: rounded) }
    public static func category(forAveragePoints points: Int) -> NavyEventResult { switch points { case 90...: return .init(points: points, category: .outstanding, level: points >= 100 ? .high : points >= 95 ? .medium : .low); case 75...89: return .init(points: points, category: .excellent, level: points >= 85 ? .high : points >= 80 ? .medium : .low); case 60...74: return .init(points: points, category: .good, level: points >= 70 ? .high : points >= 65 ? .medium : .low); case 55...59: return .init(points: points, category: .satisfactory, level: .high); case 50...54: return .init(points: points, category: .satisfactory, level: .medium); case 45...49: return .init(points: points, category: .probationary, level: .none); default: return .init(points: points, category: .failure, level: .none) } }
