// MARK: - Shared helpers
public enum FitnessTime {
    public static func seconds(minutes: Int, seconds: Int) -> Int { max(0, minutes * 60 + seconds) }
    public static func display(_ totalSeconds: Int) -> String { String(format: "%d:%02d", totalSeconds / 60, totalSeconds % 60) }
}